    ["{npc:7882}: the {item:9250}, if the cove gave you one"] = "{npc:7882}：{item:9250}，如果海湾里拿到了的话",
    ["{npc:7900} in {area:1116} sends you to {npc:7771} at the {area:1938} in {zone:1446}, where the {zone:1446} guide stops for his dig."] = "{area:1116}的{npc:7900}会让你去找{zone:1446}{area:1938}的{npc:7771}，{zone:1446}指南正好会在他的挖掘场停留。",
    ["{npc:7916}' next task sends you back to Ranshalla in {zone:1452}, behind the route now: skip it."] = "{npc:7916}的后续任务要你回{zone:1452}找兰莎尔拉，现在走回头路了：跳过。",
    ["{npc:7916}: the wildkin feathers lie along {zone:1452}'s road, on the next guide; {npc:7916} takes them on the Plaguelands guide's way through: keep it"] = "{npc:7916}：枭兽羽毛沿{zone:1452}大路散布，下一份指南会收集；等瘟疫之地指南路过这里时再交给{npc:7916}：先留着",
    ["{npc:7916}: {quest:3661}, the feathers from the {zone:1425}"] = "{npc:7916}：{quest:3661}，收集自{zone:1425}的羽毛",
