    ["{zone:1454}'s main gate is just west of {area:817}. {npc:268701} stands by the bank in the {object:172982}; {object:173016} is a few steps north."] = "{zone:1454}正门就在{area:817}正西边。{npc:268701}站在{object:172982}的银行旁；往北走几步就是{object:173016}。",
    ["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
    ["{zone:2652} is done. Ride back north through the {area:2657} and west along {area:405}'s southern edge to {area:2408} and fly to {area:1637}: the next guide picks up there, with the {zone:1444} guide's hand-ins. Keep your hearthstone (bound at {area:1099}): the next guide uses it to get from {area:1637} back to {area:1099}."] = "{zone:2652}完成了。沿{area:2657}往北骑回去，再沿{area:405}南边缘往西到{area:2408}，飞往{area:1637}：下一个指南从那里继续，先交{zone:1444}指南的任务。留着炉石（绑定在{area:1099}）：下一个指南要用它从{area:1637}回到{area:1099}。",
}
